"""
Step 4: Run Cosmos Transfer inference.

Usage:
    # Single spec:
    python scripts/04_run_cosmos_transfer.py \
        --spec path/to/spec.json \
        --output-dir path/to/output/ \
        --cosmos-repo /path/to/cosmos-transfer2.5

    # From prompts JSON (generated by step 2) + seg mask:
    python scripts/04_run_cosmos_transfer.py \
        --prompts path/to/prompts.json \
        --video path/to/video.mp4 \
        --seg-mask path/to/seg_mask.mp4 \
        --output-dir path/to/outputs/ \
        --cosmos-repo /path/to/cosmos-transfer2.5
"""

import argparse
import json
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from src.config import TransferWeights
from src.transfer import build_spec, write_spec, run_inference, run_batch_inference


def main():
    parser = argparse.ArgumentParser(description="Run Cosmos Transfer inference")

    # Mode 1: Single spec file
    parser.add_argument("--spec", help="Pre-built spec JSON file")

    # Mode 2: Build from prompts
    parser.add_argument("--prompts", help="Prompts JSON from step 2")
    parser.add_argument("--video", help="Input video path")
    parser.add_argument("--seg-mask", help="Segmentation mask path")

    # Weights
    parser.add_argument("--edge", type=float, default=0.5)
    parser.add_argument("--vis", type=float, default=0.025)
    parser.add_argument("--depth", type=float, default=0.2)
    parser.add_argument("--seg", type=float, default=0.175)
    parser.add_argument("--guidance", type=int, default=4)

    # Output
    parser.add_argument("--output-dir", "-o", required=True)
    parser.add_argument("--cosmos-repo", required=True, help="Path to cosmos-transfer2.5")
    parser.add_argument("--no-disable-guardrails", action="store_true")

    args = parser.parse_args()
    disable_guardrails = not args.no_disable_guardrails

    if args.spec:
        # Mode 1: single spec
        run_inference(args.spec, args.output_dir, args.cosmos_repo, disable_guardrails)

    elif args.prompts:
        # Mode 2: batch from prompts JSON
        if not args.video:
            parser.error("--video required when using --prompts")

        with open(args.prompts) as f:
            prompts = json.load(f)

        weights = TransferWeights(
            edge=args.edge, vis=args.vis, depth=args.depth, seg=args.seg
        )

        specs = []
        for p in prompts:
            variation = p["variation"].replace(" ", "_")[:40]
            name = f"transfer_{variation}"
            spec = build_spec(
                name=name,
                prompt=p["prompt"],
                video_path=args.video,
                guidance=args.guidance,
                weights=weights,
                seg_mask_path=args.seg_mask,
            )
            specs.append((spec, name))

        run_batch_inference(
            specs, args.cosmos_repo, args.output_dir, disable_guardrails
        )

    else:
        parser.error("Either --spec or --prompts is required")


if __name__ == "__main__":
    main()
